 function translators(focusKey){level='translators';currentSeason=null;currentEpisode=null;info.voice=orderedVoices(info.voice,preference);root.empty();hero('HDREZKA',title,info.is_series?'Выберите перевод — список сезонов обновится автоматически':'Выберите перевод');var resume=info.is_series?resumeChoice():null,selected=selectedVoice();if(resume)add('Продолжить — С'+resume.season+' Е'+resume.episode,continueMeta(resume,selected),'▶',function(){continueSeries(resume)},false,'continue').addClass('rezka4-continue');info.voice.forEach(function(v){add(v.name,'Доступная озвучка','Перевод',function(){currentVoice=v;rememberVoice(v);if(info.is_series){msg('Получаем сезоны для '+v.name+'…',true);voiceEpisodes(v,function(){seasons(v)},function(x){msg(x,false)})}else{msg('Получаем доступные качества…',true);requestStream(info,v,null,null,function(q){var chosen=automaticQuality(q,preference,false);if(chosen)qualities(v,null,null,q,qualityKey(chosen),chosen);else qualities(v,null,null,q)},function(x){msg(x,false)})}},false,'voice:'+v.id)});add('Моя HDREZKA','Открыть избранное Lampa','★',openMy,false,'my-rezka');if(Lampa.Favorite&&Lampa.Favorite.toggle){var bookmarked=favoriteOverride===null?nativeFavoriteStatus(movie):favoriteOverride;add(bookmarked?'★ В избранном':'☆ В избранное',bookmarked?'Нажмите, чтобы удалить из закладок Lampa':'Добавить в Мою HDREZKA и закладки Lampa',bookmarked?'★':'☆',function(){var added=toggleNativeFavorite(movie);if(added===null){try{Lampa.Noty.show('HDREZKA: не удалось изменить избранное')}catch(e){}return}favoriteOverride=added;if(added){var chosen=currentVoice||selectedVoice(),cached=chosen&&voiceCache[String(chosen.id)];if(cached)rememberCatalog(chosen,cached,true)}else clearCatalogPreference();try{Lampa.Noty.show(added?'HDREZKA: добавлено в избранное':'HDREZKA: удалено из избранного')}catch(e){}translators('favorite-toggle')},false,'favorite-toggle')}focus(focusKey||(resume?'continue':(selected?'voice:'+selected.id:null)))}
